set local plpgsql.check_asserts=on;
create function pg_temp.jsid(n integer) returns uuid language sql immutable as $$select ('bc170000-aaaa-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
grant execute on function pg_temp.jsid(integer) to authenticated;
insert into public.tenants(id,slug,display_name,status) values(pg_temp.jsid(1),'job-search-a','Synthetic search A','active'),(pg_temp.jsid(2),'job-search-b','Synthetic search B','active');
insert into auth.users(id,email,banned_until) values(pg_temp.jsid(10),'job-search@example.invalid','infinity');
insert into public.profiles(id,tenant_id,role) values(pg_temp.jsid(10),pg_temp.jsid(1),'viewer') on conflict(id) do update set tenant_id=excluded.tenant_id,role=excluded.role;
insert into public.companies(id,tenant_id,name,address_text,postcode) values(pg_temp.jsid(20),pg_temp.jsid(1),'Synthetic plumbing','2 Example Street','ZZ1 1ZZ'),(pg_temp.jsid(21),pg_temp.jsid(2),'Foreign customer','Foreign address','ZZ9 9ZZ');
insert into public.jobs(id,tenant_id,title,job_number,source_system,external_id,customer_company_id,metadata)
 select pg_temp.jsid(100+n),pg_temp.jsid(1),'008. Servicing',lpad(n::text,3,'0'),'synthetic-search',n::text,pg_temp.jsid(20),'{"private":"NEVER_RETURN"}' from generate_series(1,26)n;
insert into public.jobs(id,tenant_id,title,job_number,source_system,external_id,customer_company_id) values(pg_temp.jsid(200),pg_temp.jsid(2),'Foreign job','001','synthetic-search','200',pg_temp.jsid(21)),(pg_temp.jsid(201),pg_temp.jsid(1),'Literal 50%_ job','X','synthetic-search','201',null);
set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='bc170000-aaaa-4000-8000-000000000010';set local role authenticated;
do $$begin begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','test search');raise exception 'Tenant viewer admitted';exception when insufficient_privilege then null;end;end$$;
reset role;
insert into public.platform_authority_grants(profile_id,permission,granted_by,effective_to) values(pg_temp.jsid(10),'platform.controlplane.view','fixture',clock_timestamp()+interval '5 minutes');
set local role authenticated;
do $$begin begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','test search');raise exception 'View-only admitted';exception when insufficient_privilege then null;end;end$$;
reset role;
insert into public.platform_authority_grants(profile_id,permission,granted_by,effective_to) values(pg_temp.jsid(10),'platform.controlplane.admin','fixture',clock_timestamp()+interval '5 minutes');
set local role authenticated;
do $$declare a jsonb;b jsonb;begin
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'001','find leading zero');
 assert jsonb_array_length(a->'rows')=1 and a#>>'{rows,0,fields,job_number}'='001';
 assert a#>>'{rows,0,fields,title}'='008. Servicing' and a#>>'{rows,0,fields,customer}'='Synthetic plumbing';
 assert a->>'actor_id'=auth.uid()::text and a->>'tenant_id'=pg_temp.jsid(1)::text;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'008.','find service category');
 assert jsonb_array_length(a->'rows')=25 and a->>'next_after'=pg_temp.jsid(125)::text;
 b:=public.learn_operator_job_search(pg_temp.jsid(1),'008.','find second page',(a->>'next_after')::uuid);
 assert jsonb_array_length(b->'rows')=1 and b->'next_after'='null'::jsonb;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'sYnTheTic PLUMBING','find customer');assert jsonb_array_length(a->'rows')=25;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'ZZ1 1ZZ','find address');assert jsonb_array_length(a->'rows')=25;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'%_','literal wildcard');assert jsonb_array_length(a->'rows')=1 and a#>'{rows,0,fields,customer}'='null'::jsonb and a#>'{rows,0,fields,address}'='null'::jsonb;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'Foreign','exclude other tenant');assert a->'rows'='[]'::jsonb;
 a:=public.learn_operator_job_search(pg_temp.jsid(2),'001','explicit second client');assert jsonb_array_length(a->'rows')=1;
 a:=public.learn_operator_job_search(pg_temp.jsid(1),'','browse published jobs');assert jsonb_array_length(a->'rows')=25 and a::text not like '%NEVER_RETURN%';
 begin perform public.learn_operator_job_search(pg_temp.jsid(1),repeat('x',121),'invalid query');raise exception 'Long query admitted';exception when invalid_parameter_value then null;end;
 begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','');raise exception 'No reason admitted';exception when invalid_parameter_value then null;end;
end$$;
reset role;
do $$begin
 assert (select count(*)=9 from public.controlplane_change_log where actor=pg_temp.jsid(10)::text and source='openfolk-job-search');
 assert not exists(select 1 from public.controlplane_change_log where actor=pg_temp.jsid(10)::text and after::text like '%Synthetic%');
 assert (select tenant_id=pg_temp.jsid(1) and role='viewer' from public.profiles where id=pg_temp.jsid(10));
end$$;
insert into public.view_as_context(tenant_id,actor_user_id,subject_kind,subject_ref,reason) values(pg_temp.jsid(1),pg_temp.jsid(10),'role','viewer','fixture');
set local role authenticated;
do $$begin begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','view as denied');raise exception 'View-as admitted';exception when insufficient_privilege then null;end;end$$;
reset role;update public.view_as_context set ended_at=clock_timestamp() where actor_user_id=pg_temp.jsid(10);
create function pg_temp.reject_js_audit() returns trigger language plpgsql as $$begin raise exception 'audit_failure' using errcode='P0001';end$$;
create trigger synthetic_job_search_audit before insert on public.controlplane_change_log for each row execute function pg_temp.reject_js_audit();
set local role authenticated;
do $$begin begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','audit unavailable');raise exception 'Unaudited response' using errcode='XX000';exception when raise_exception then if sqlerrm<>'audit_failure' then raise;end if;end;end$$;
reset role;drop trigger synthetic_job_search_audit on public.controlplane_change_log;
update public.platform_authority_grants set effective_to=clock_timestamp()-interval '1 second' where profile_id=pg_temp.jsid(10);
set local role authenticated;
do $$begin begin perform public.learn_operator_job_search(pg_temp.jsid(1),'001','revoked');raise exception 'Revoked admitted';exception when insufficient_privilege then null;end;end$$;
reset role;
do $$begin
 assert not has_function_privilege('anon','public.learn_operator_job_search(uuid,text,text,uuid)','execute');
 assert not has_function_privilege('service_role','public.learn_operator_job_search(uuid,text,text,uuid)','execute');
 assert not exists(select 1 from public.platform_jobs where tenant_id in(pg_temp.jsid(1),pg_temp.jsid(2)));
end$$;
